            enter {
                CA_mode = 1;
                software_control = 1;
                control_released = 0;
                pump_speed_source = 1;
                alarm_display = 0;
                alarm_sound = 0;
            }
        }

        state NormalAutocontrol {
            during {
                sensor_buffer_bp = blood_pressure;
                if [blood_pressure > target_blood_pressure] {
